        { name: 'right', dr: 0, dc: 1 }
      ];

      const prev = Array.from({ length: mazeSize }, () => Array(mazeSize).fill(null));
      const queue = [{ row: 0, col: 0 }];
      prev[0][0] = { row: -1, col: -1, move: null };

      while (queue.length) {
        const cur = queue.shift();
        if (cur.row === mazeSize - 1 && cur.col === mazeSize - 1) break;

        for (const d of dirs) {
          const nr = cur.row + d.dr;
          const nc = cur.col + d.dc;
          if (
            nr >= 0 && nr < mazeSize &&
            nc >= 0 && nc < mazeSize &&
            mazeLayout[nr][nc] !== '#' &&
            prev[nr][nc] === null
          ) {
            prev[nr][nc] = { row: cur.row, col: cur.col, move: d.name };
            queue.push({ row: nr, col: nc });
          }
        }
