      const moves = [];
      let r = mazeSize - 1;
      let c = mazeSize - 1;
      while (!(r === 0 && c === 0)) {
        const step = prev[r][c];
        if (!step) return;
        moves.push(step.move);
        r = step.row;
        c = step.col;
      }
      moves.reverse();

      for (const m of moves) {
        moveCharacter(m);
      }
    }

